//! Identity of the compiler producing the executable, and readable source provenance.
use crate::frontend::source::SourceFile;
use std::fmt::Write;

pub(crate) const VERSION: &str = env!("CARGO_PKG_VERSION");
pub(crate) const REVISION: &str = env!("RUSK_BUILD_REVISION");
pub(crate) const MODIFIED: bool = matches!(env!("RUSK_BUILD_MODIFIED").as_bytes(), b"true");
pub(crate) const SOURCE_URL: &str = env!("CARGO_PKG_REPOSITORY");

pub(crate) fn cpp_header(optimize: bool) -> String {
    format!(
        "// Generated by Rusk {VERSION}. C++20.\n// Compiler source: {SOURCE_URL}\n// Revision: {}; modified: {MODIFIED}; optimize: {optimize}\n",
        if REVISION.is_empty() {
            "unknown"
        } else {
            REVISION
        }
    )
}

pub(crate) fn cpp_constants() -> String {
    let mut output = String::new();
    for (name, value) in [
        ("version", VERSION),
        ("revision", REVISION),
        ("source_url", SOURCE_URL),
    ] {
        writeln!(
            output,
            "inline constexpr const char* rusk_compiler_{name} = {};",
            serde_json::to_string(value).unwrap()
        )
        .unwrap();
    }
    writeln!(
        output,
        "inline constexpr bool rusk_compiler_modified = {MODIFIED};"
    )
    .unwrap();
    output
}

pub(crate) fn append_sources(output: &mut String, sources: &[SourceFile]) {
    for source in sources {
        writeln!(
            output,
            "\n// Rusk source: {}",
            serde_json::to_string(&source.name).unwrap()
        )
        .unwrap();
        // A fixed suffix prevents C++ phase-2 line splicing, even for a Rusk
        // comment ending with a backslash. JSON below retains exact input text.
        for line in source.text.split('\n') {
            let line = line.replace('\r', "\\r").replace('\0', "\\0");
            writeln!(output, "//| {line} |rusk-eol|").unwrap();
        }
        let exact = serde_json::json!({"name": source.name, "text": source.text});
        writeln!(output, "// Rusk source JSON: {exact}").unwrap();
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn source_comments_preserve_exact_text_without_comment_terminators_or_splices() {
        let text = "// comment */ \\\r\nwt 1;\n";
        let mut output = String::new();
        append_sources(
            &mut output,
            &[SourceFile {
                name: "main\n.rusk".into(),
                text: text.into(),
            }],
        );
        for line in output.lines() {
            assert!(!line.trim_end().ends_with('\\'));
        }
        let exact = output
            .lines()
            .find_map(|line| line.strip_prefix("// Rusk source JSON: "))
            .unwrap();
        let exact: serde_json::Value = serde_json::from_str(exact).unwrap();
        assert_eq!(exact["text"], text);
        assert_eq!(exact["name"], "main\n.rusk");
    }
}
